"""Hand-transcribed witnesses and matched ERA targets for the selected ZIP images.

The first choice in each source row is the content answer. The builder independently
evaluates the keyed operation over these read-offs, then balances the displayed options.
"""


def q(question, options, expression, evidence, rule, application, enhanced_e=None, enhanced_r=None):
    return dict(question=question, values=options.split("|"), expression=expression,
                ordinary=dict(e=evidence,r=rule,a=application),
                enhanced=dict(e=enhanced_e or evidence,r=enhanced_r or rule,a=application))


def group(sid, kind, facts, *questions):
    return dict(sid=sid,kind=kind,facts=facts,questions=questions)


